const formioUser = JSON.parse(localStorage.getItem('formioUser'));
const roles = formioUser?.realm_access?.roles || [];

const acceptedRoles = [
  'ROLE_KLACHTEN_KLACHTENCOORDINATOR',
  'ROLE_KLACHTEN_KLACHTENCOORDINATOR_GGD',
  'ROLE_KLACHTEN_KLACHTENCOORDINATOR_VTH'
];

const hasRoleKlachtenKlachtencoordinator = acceptedRoles.some(role =>
  roles.includes(role)
);

show =
  data.openZaak?.statusOmschrijving !== 'Afgehandeld' &&
  hasRoleKlachtenKlachtencoordinator;

